css:
/* Endversion · Design-Bündel (inhaltsfrei). Erzeugt aus der Owner-Vorschau; Vorschau-Chrome entfernt. Nicht von Hand ändern. */
/* ===== tokens.css ===== */
:root{

  --navy-900:#12161F;--navy-800:#1A1F2E;--navy-700:#262C3C;--navy-600:#353C4E;
  --navy-500:#444C5F;--navy-400:#596176;--navy-300:#687083;

  --cream-50:#FBF8F2;--cream-100:#F6F0E6;--cream-200:#F1E9DC;--cream-300:#E7DCC9;
  --cream-400:#D9CBB3;--cream-500:#C7B79A;

  --amber:#F6A93B;--magenta:#C2185B;
  --grad:linear-gradient(115deg,#7A3FB0 0%,#C2185B 40%,#F2643C 76%,#F6A93B 100%);
  --succ:#2F7D3D;--succ-d:#256433;--succ-bg:#E3EDDD;--succ-fg:#245C32;--succ-bd:#A9C7A2;
  --warn:#D9722B;--warn-bg:#FAE7D6;--warn-fg:#9C5214;--warn-bd:#ECC39C;
  --info:#4B5366;--info-bg:#E6E8EE;--info-fg:#3A4763;
  --ral:#AF2B1E;--ral-bg:#F7E1DC;--ral-fg:#7E1D14;--ral-bd:#E7B4AA;
  --ground:#EFE6D6;--surface:#FFFDF9;--line:#E1D5BE;

  --magenta-d:#A5124D;--purple:#7A3FB0;--orange:#F2643C;
  --part-bg:#EBE4F3;--part-fg:#5A3E86;--ground-rail:#EADFCB;


  --serif:"Fraunces",Georgia,serif;
  --sans:"Inter",system-ui,-apple-system,"Segoe UI",sans-serif;
  --fs-mini:10.5px;--fs-s:11.5px;--fs-m:12.5px;--fs-text:13.5px;--fs-l:14px;
  --fs-zahl:16px;          
  --fs-karte:22px;--fs-seite:25px;--fs-seite-touch:21px;


  --sh-sm:0 1px 2px rgba(26,31,46,.06),0 1px 3px rgba(26,31,46,.05);
  --sh-md:0 2px 6px rgba(26,31,46,.08),0 6px 16px rgba(26,31,46,.06);
  --sh-lg:0 14px 40px rgba(26,31,46,.20);
  --sh-primaer:0 2px 8px rgba(26,31,46,.18);
  --sh-erledigen:0 2px 8px rgba(47,125,61,.24);
  --sh-marke:0 4px 14px rgba(120,50,120,.34);
  --sh-leiste:0 -8px 24px rgba(18,22,31,.22);
  --scrim:rgba(18,22,31,.55);
  --ease:cubic-bezier(.2,.7,.2,1);


  --fokus:var(--navy-500);--fokus-dialog:var(--amber);


  --r-xs:6px;--r-s:8px;--r-m:10px;--r-btn:11px;--r-l:12px;--r-eintrag:13px;--r-kachel:16px;--r-dialog:18px;--r-voll:999px;

  --a-1:4px;--a-2:6px;--a-3:8px;--a-4:10px;--a-5:12px;--a-6:14px;--a-7:16px;--a-8:18px;--a-9:20px;--a-10:24px;


  --touch:48px;


  --seitenleiste:238px;--kopf:66px;--kopf-touch:58px;--kopf-werkstatt:62px;
  --dock:66px;--aktionsleiste:80px;--aktionsleiste-handy:74px;--streifen:3px;


  --ref-desktop-b:1914px;--ref-desktop-h:917px;
  --ref-tablet-b:1220px;--ref-tablet-h:880px;
  --ref-handy-b:390px;--ref-handy-h:844px;


  --ground:#F4F2EE;--ground-rail:#EFEDE8;--surface:#FFFFFF;--line:#E4E0D8;
  --rand:#D5D0C7;      
  --flaeche:#F7F6F3;   
}

/* ===== komponenten.css ===== */
.kr-app,.kr-app *{box-sizing:border-box}
.kr-app{position:relative;width:100%;height:100%;overflow:hidden;font-family:var(--sans);color:var(--navy-900);background:var(--ground);-webkit-font-smoothing:antialiased;font-size:var(--fs-text);line-height:1.4}
:where(.kr-app) :where(button,input,select,textarea){font:inherit;color:inherit}
:where(.kr-app) :where(button){touch-action:manipulation;cursor:pointer}
.kr-app :focus-visible{outline:2px solid var(--fokus);outline-offset:2px}
.kr-ebene :focus-visible{outline-color:var(--fokus-dialog)}
.kr-i{width:1em;height:1em;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;vertical-align:-.14em;flex:none}
.kr-streifen{height:var(--streifen);background:var(--grad);flex:none}
.kr-scroll{overflow-y:auto;scrollbar-width:none}.kr-scroll::-webkit-scrollbar{display:none}
.kr-id{font-family:var(--serif);font-weight:500;color:var(--navy-700)}
.kr-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}


.kr-btn{min-height:var(--touch);padding:0 16px;border:1px solid var(--rand);border-radius:var(--r-btn);background:var(--surface);color:var(--navy-800);font-size:13px;font-weight:600;display:inline-flex;align-items:center;justify-content:center;gap:7px;white-space:nowrap;transition:background .15s,border-color .15s}
.kr-btn:hover{background:var(--cream-100)}
.kr-btn .kr-i{font-size:16px}
.kr-btn--primaer{background:var(--navy-800);border-color:var(--navy-800);color:#fff;box-shadow:var(--sh-primaer)}.kr-btn--primaer:hover{background:var(--navy-700)}
.kr-btn--erledigen{background:var(--succ);border-color:var(--succ);color:#fff;box-shadow:var(--sh-erledigen)}.kr-btn--erledigen:hover{background:var(--succ-d)}
.kr-btn--gefaehrlich{background:var(--ral);border-color:var(--ral);color:#fff}.kr-btn--gefaehrlich:hover{background:var(--ral-fg)}
.kr-btn--marke{background:var(--grad);border:0;color:#fff;box-shadow:var(--sh-marke)}
.kr-btn--sekundaer{border:1.5px solid var(--rand)}
.kr-btn--leise{background:transparent;color:var(--navy-500);font-weight:500}
.kr-btn--icon{width:var(--touch);padding:0}
.kr-btn--block{width:100%}
.kr-btn:disabled,.kr-btn[aria-disabled="true"]{opacity:.42;cursor:not-allowed;box-shadow:none}


.kr-chip{display:inline-flex;align-items:center;gap:5px;padding:3px 9px;border-radius:var(--r-voll);font-size:var(--fs-mini);font-weight:700;line-height:1.3;white-space:nowrap;background:#ECEAE5;color:var(--navy-600)}
.kr-chip .kr-i{font-size:12px}
.kr-chip--ok{background:var(--succ-bg);color:var(--succ-fg)}
.kr-chip--warn{background:var(--warn-bg);color:var(--warn-fg)}
.kr-chip--rot{background:var(--ral-bg);color:var(--ral-fg)}
.kr-chip--info{background:var(--info-bg);color:var(--info-fg)}
.kr-chip--marke{background:var(--magenta);color:#fff}
.kr-chip--teil{background:var(--part-bg);color:var(--part-fg)}
.kr-chip--dunkel{background:var(--navy-800);color:#fff}
.kr-punkt{width:10px;height:10px;border-radius:50%;flex:none;background:var(--navy-300)}
.kr-punkt--ok{background:var(--succ)}.kr-punkt--warn{background:var(--warn)}.kr-punkt--rot{background:var(--ral);box-shadow:0 0 0 4px rgba(175,43,30,.14)}.kr-punkt--info{background:var(--info)}


.kr-zustand{display:flex;align-items:center;gap:12px;min-height:var(--touch);padding:8px 10px 8px 14px;border-radius:var(--r-l);background:var(--surface);border:1px solid var(--line);font-size:13px;color:var(--navy-600)}
.kr-zustand>.kr-i{font-size:16px;color:var(--navy-400)}
.kr-zustand-text{flex:1;min-width:0}
.kr-zustand--fehler{background:var(--ral-bg);border-color:var(--ral-bd);color:var(--ral-fg)}.kr-zustand--fehler>.kr-i{color:var(--ral)}
.kr-zustand--gesperrt{background:var(--cream-100);color:var(--navy-500)}
.kr-zustand--laedt{color:var(--navy-500)}
.kr-drehen{width:14px;height:14px;border-radius:50%;border:2px solid var(--cream-400);border-top-color:var(--navy-500);animation:kr-drehen .7s linear infinite;flex:none}
.kr-skelett{height:12px;border-radius:6px;background:linear-gradient(90deg,var(--cream-200),var(--cream-100),var(--cream-200));background-size:200% 100%;animation:kr-schimmer 1.2s linear infinite}
@keyframes kr-drehen{to{transform:rotate(360deg)}}
@keyframes kr-schimmer{to{background-position:-200% 0}}


.kr-ausgrau{display:flex;align-items:center;gap:10px;min-height:40px;padding:6px 12px;border-radius:var(--r-m);font-size:12.5px;color:var(--navy-400);pointer-events:none;user-select:none}
.kr-ausgrau .kr-i{font-size:15px}
.kr-ausgrau-text{flex:1;min-width:0;text-wrap:pretty;line-height:1.3} 
.kr-ausgrau-tag{white-space:nowrap;font-size:9.5px;letter-spacing:.04em;text-transform:uppercase;font-weight:700;border-radius:var(--r-voll);padding:3px 9px;flex:none}
.kr-ausgrau--aufbau{border:1px dashed var(--cream-500);background:repeating-linear-gradient(135deg,transparent 0 9px,rgba(139,115,85,.05) 9px 18px)}
.kr-ausgrau--aufbau .kr-ausgrau-tag{white-space:nowrap;background:var(--info-bg);color:var(--info-fg)}
.kr-ausgrau--klaerung{border:1px dotted var(--warn-bd);background:var(--cream-100)}
.kr-ausgrau--klaerung .kr-ausgrau-tag{white-space:nowrap;background:var(--warn-bg);color:var(--warn-fg)}
.kr-ausgrau--nav{color:var(--navy-400);border-color:var(--navy-600);background:transparent}
.kr-ausgrau--knopf{display:inline-flex;min-height:var(--touch);border-radius:var(--r-btn)}


.kr-shell{display:grid;grid-template-columns:var(--seitenleiste) minmax(0,1fr);grid-template-rows:var(--kopf) minmax(0,1fr);height:calc(100% - var(--streifen))}
.kr-kopf{grid-column:1/3;display:flex;align-items:center;gap:14px;padding:0 20px;border-bottom:1px solid var(--line);background:var(--surface);height:var(--kopf);flex:none}
.kr-marke{display:flex;align-items:center;gap:11px;flex:none;background:none;border:0;padding:0}
.kr-shell .kr-marke{width:198px}
.kr-logo{width:38px;height:38px;border-radius:10px;background:var(--navy-800);color:var(--cream-50);font-family:var(--serif);font-size:15px;display:grid;place-items:center;letter-spacing:.5px;flex:none}
.kr-marke-name{font-family:var(--serif);font-size:16px;letter-spacing:1.5px;color:var(--navy-800)}
.kr-suche{flex:1;min-width:0;height:44px;background:var(--flaeche);border:1.5px solid var(--rand);border-radius:var(--r-btn);display:flex;align-items:center;gap:11px;padding:0 15px;box-shadow:var(--sh-sm);text-align:left}
.kr-suche>.kr-i{font-size:18px;color:var(--navy-500)}
.kr-suche-ph{flex:1;font-size:14px;color:var(--navy-400);font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.kr-suche-kbd{white-space:nowrap;font-size:11px;color:var(--navy-400);border:1px solid var(--cream-400);border-radius:6px;padding:2px 7px;background:var(--surface)}
.kr-datum{font-size:12px;color:var(--navy-500);text-align:right;line-height:1.35;flex:none;white-space:nowrap}.kr-datum b{color:var(--navy-800);font-weight:600}
.kr-avatar{width:var(--touch);height:var(--touch);border-radius:50%;background:var(--navy-800);color:#fff;display:grid;place-items:center;font-size:13px;font-weight:700;flex:none;border:0}
.kr-plus{width:var(--touch);height:var(--touch);border-radius:50%;background:var(--grad);color:#fff;border:0;display:grid;place-items:center;font-size:22px;box-shadow:var(--sh-marke);flex:none}
.kr-plus-menue{position:absolute;z-index:40;min-width:240px;background:var(--surface);border:1px solid var(--rand);border-radius:var(--r-l);box-shadow:var(--sh-lg);padding:6px;display:flex;flex-direction:column;gap:2px}
.kr-menue-el{min-height:var(--touch);display:flex;align-items:center;gap:10px;padding:0 12px;border:0;border-radius:var(--r-s);background:transparent;font-size:13.5px;font-weight:600;color:var(--navy-800);text-align:left}
.kr-menue-el:hover{background:var(--cream-100)}.kr-menue-el .kr-i{font-size:18px;color:var(--navy-500)}

.kr-seitenleiste{background:var(--navy-800);padding:14px 12px;display:flex;flex-direction:column;gap:4px;overflow-y:auto}
.kr-nav{white-space:nowrap;display:flex;align-items:center;gap:11px;min-height:var(--touch);border-radius:10px;padding:0 13px;font-size:13.5px;font-weight:500;color:var(--cream-200);border:1px solid transparent;background:transparent;text-align:left;width:100%}
.kr-nav .kr-i{font-size:18px;color:var(--navy-300)}
.kr-nav:hover{background:var(--navy-700);color:#fff}
.kr-nav--aktiv,.kr-nav--aktiv:hover{background:var(--cream-50);color:var(--navy-900);font-weight:600;box-shadow:inset 0 0 0 2px var(--amber)}
.kr-nav--aktiv .kr-i{color:var(--navy-800)}
.kr-nav--schnell{background:var(--navy-700);color:#fff;border-color:var(--navy-600)}.kr-nav--schnell .kr-i{color:var(--amber)}
.kr-nav-badge{margin-left:auto;background:var(--navy-600);color:var(--cream-100);border-radius:var(--r-voll);min-width:20px;height:20px;padding:0 6px;font-size:11px;font-weight:700;display:inline-flex;align-items:center;justify-content:center}
.kr-nav-badge--rot{background:var(--ral);color:#fff}
.kr-nav-trenner{height:1px;background:var(--navy-600);margin:9px 8px}
.kr-nav-unten{margin-top:auto}
.kr-inhalt{background:var(--ground);overflow-y:auto;padding:18px 22px 24px;min-width:0;scrollbar-width:none}
.kr-inhalt::-webkit-scrollbar{display:none}


.kr-tshell{display:flex;flex-direction:column;height:calc(100% - var(--streifen));position:relative}
.kr-tshell>.kr-kopf{height:var(--kopf-touch);padding:0 14px;gap:10px}
.kr-tshell .kr-logo{width:36px;height:36px;font-size:13px}
.kr-tshell .kr-suche{height:var(--touch)} 
.kr-tshell .kr-marke{min-width:var(--touch);min-height:var(--touch);justify-content:center} 
.kr-tshell>.kr-inhalt{flex:1;padding:14px 14px calc(var(--dock) + 16px)}
.kr-dock{position:absolute;left:0;right:0;bottom:0;height:var(--dock);background:var(--navy-800);display:flex;align-items:stretch;padding:7px 8px;gap:2px;box-shadow:var(--sh-leiste);z-index:6}
.kr-dock-el{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;border-radius:12px;color:var(--cream-200);font-size:10.5px;font-weight:600;border:0;background:transparent;position:relative;min-width:0}
.kr-dock-el .kr-i{font-size:20px;color:var(--navy-300)}
.kr-dock-el--aktiv{background:var(--cream-50);color:var(--navy-900);box-shadow:inset 0 0 0 2px var(--amber)}.kr-dock-el--aktiv .kr-i{color:var(--navy-800)}
.kr-dock-badge{position:absolute;top:3px;right:calc(50% - 24px);background:var(--ral);color:#fff;border-radius:var(--r-voll);min-width:17px;height:17px;padding:0 4px;font-size:10px;font-weight:700;display:inline-flex;align-items:center;justify-content:center}
.kr-schnellleiste{display:flex;gap:8px;margin:0 0 12px}
.kr-schnellleiste .kr-btn{flex:1}


.kr-wshell>.kr-kopf{height:var(--kopf-werkstatt);padding:0 18px}
.kr-wshell>.kr-inhalt{flex:1;padding:18px 20px calc(var(--aktionsleiste) + 18px)}
.kr-aktionsleiste{position:absolute;left:0;right:0;bottom:0;height:var(--aktionsleiste);background:var(--navy-800);display:flex;align-items:center;gap:10px;padding:0 16px;box-shadow:var(--sh-leiste);z-index:8}
.kr-aktion{flex:1;height:56px;border-radius:13px;display:flex;align-items:center;justify-content:center;gap:9px;font-size:13.5px;font-weight:600;background:var(--navy-700);color:var(--cream-100);border:1px solid var(--navy-600);padding:0 14px;white-space:nowrap;min-width:0}
.kr-aktion .kr-i{font-size:19px;color:var(--cream-200)}
.kr-aktion--primaer{flex:1.5;background:var(--grad);border-color:transparent;color:#fff;font-weight:700;box-shadow:var(--sh-marke)}.kr-aktion--primaer .kr-i{color:#fff}
.kr-aktion--ruhig{background:transparent}


.kr-seite-kopf{display:flex;align-items:center;gap:12px;margin:0 0 14px;flex-wrap:wrap}
.kr-seite-titel{font-family:var(--serif);font-size:var(--fs-seite);font-weight:500;letter-spacing:-.3px;margin:0;line-height:1.15;flex:1;min-width:0}
.kr-seite-werkzeug{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.kr-stapel{display:flex;flex-direction:column;gap:14px}
.kr-raster{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,340px),1fr));gap:14px;align-items:start}
.kr-spalten{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(0,1fr);gap:16px;align-items:start}


.kr-hb{display:flex;flex-direction:column;gap:8px}
.kr-hb-label{display:flex;align-items:center;gap:9px;font-size:12px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--navy-800);margin:0 0 2px}
.kr-hb-label .kr-i{font-size:15px;color:var(--warn-fg)}
.kr-hb-eintrag{position:relative;display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:14px;align-items:center;background:var(--surface);border:1px solid var(--line);border-left:4px solid var(--rand);border-radius:var(--r-eintrag);padding:10px 12px 10px 14px;box-shadow:var(--sh-sm)}
.kr-hb-eintrag--konflikt{border-left-color:var(--ral);}
.kr-hb-eintrag--warnung{border-left-color:var(--warn)}
.kr-hb-eintrag--entscheidung{border-left-color:var(--info);}
.kr-hb-eintrag--konflikt .kr-punkt{background:var(--ral);box-shadow:0 0 0 4px rgba(175,43,30,.14)}
.kr-hb-eintrag--warnung .kr-punkt{background:var(--warn)}
.kr-hb-eintrag--entscheidung .kr-punkt{background:var(--info)}
.kr-hb-main{min-width:0}
.kr-hb-titel{font-size:14px;font-weight:600;line-height:1.35;text-wrap:pretty;overflow-wrap:break-word} 
.kr-hb-titel .kr-id{margin-right:8px}
.kr-hb-meta{font-size:12.5px;color:var(--navy-500);margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:22px}
.kr-hb-meta .kr-chip{margin-right:8px;vertical-align:1px}
.kr-hb-aktionen{display:flex;gap:7px;align-items:center;flex:none}
.kr-hb-status{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:var(--navy-500);font-weight:500}
.kr-hb-status--rot{color:var(--ral-fg);font-weight:600}
.kr-hb-status--info{color:var(--info-fg)}
.kr-hb-mehr{font-size:14px;font-weight:600;color:var(--navy-800);background:var(--surface);border:1.5px solid var(--rand);border-radius:var(--r-eintrag);min-height:56px;box-shadow:var(--sh-sm)}
.kr-hb-mehr .kr-i{font-size:20px}
.kr-hb-mehr:hover{background:var(--flaeche)}


.kr-kachel{background:var(--surface);border:1px solid var(--line);border-radius:var(--r-kachel);box-shadow:var(--sh-sm);display:flex;flex-direction:column;overflow:hidden}
.kr-kachel-kopf{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line);min-height:var(--touch)}
.kr-kachel-titel{display:flex;align-items:center;gap:10px;font-size:12px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--navy-800);margin:0}
.kr-kachel-ic{width:28px;height:28px;border-radius:8px;display:grid;place-items:center;font-size:15px;background:var(--navy-700);color:#fff;flex:none}
.kr-kachel-ic--ok{background:var(--succ)}.kr-kachel-ic--info{background:var(--info-bg);color:var(--info-fg)}.kr-kachel-ic--warn{background:var(--warn);}
.kr-kachel-zahl{font-family:var(--serif);font-size:var(--fs-zahl);color:var(--navy-700)}
.kr-kachel-inhalt{padding:4px 6px;display:flex;flex-direction:column}
.kr-kachel-inhalt>.kr-zustand,.kr-kachel-inhalt>.kr-ausgrau{margin:4px}
.kr-kachel-fuss{min-height:var(--touch);padding:0 15px;border:0;border-top:1px solid var(--line);font-size:12.5px;color:var(--navy-600);font-weight:600;display:flex;align-items:center;gap:6px;background:transparent;width:100%;text-align:left}
.kr-kachel-fuss:hover{background:var(--cream-50)}


.kr-zeile{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:11px;align-items:center;padding:8px 10px;border-radius:11px;min-height:var(--touch);background:transparent;border:0;width:100%;text-align:left}
button.kr-zeile:hover,.kr-zeile--klick:hover{background:var(--cream-100)}
.kr-zeile--karte{background:var(--surface);border:1px solid var(--line);border-radius:var(--r-l);box-shadow:var(--sh-sm);padding:9px 12px}
.kr-zeile-main{min-width:0}
.kr-zeile-t{font-size:13px;font-weight:600;color:var(--navy-900);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.kr-zeile-t .kr-id{margin-right:7px}
.kr-zeile-t .kr-chip{margin-left:7px;vertical-align:1px}
.kr-zeile-t .kr-id{font-size:12.5px}
.kr-zeile-s{font-size:11.5px;color:var(--navy-500);margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
