.kr-ebene--blatt{justify-content:flex-end;align-items:stretch;padding:0;background:rgba(18,22,31,.32)}
.kr-ebene--blatt>.kr-dialog--karte{width:min(1180px,calc(100% - 96px));max-height:none;height:100%;border-radius:var(--r-dialog) 0 0 var(--r-dialog);border-right:0}
.kr-app[data-geraet="tablet"] .kr-ebene--blatt>.kr-dialog--karte{width:min(900px,calc(100% - 96px))}
.kr-app[data-geraet="handy"] .kr-ebene--blatt{align-items:flex-end}
.kr-app[data-geraet="handy"] .kr-ebene--blatt>.kr-dialog--karte{width:100%;height:calc(100% - 28px);border-radius:18px 18px 0 0;border-right:1px solid var(--cream-300)}
.kr-app:not([data-geraet="handy"])[data-anim~="ebene"] .kr-ebene--blatt>.kr-dialog{animation:kr-blatt-r .3s var(--ease) both}
.kr-app:not([data-geraet="handy"]) .kr-ebene--zu.kr-ebene--blatt>.kr-dialog{animation:kr-blatt-r-zu .2s var(--ease) forwards!important}
.kr-blatt-zurueck{display:flex;align-items:center;gap:8px;padding:6px 14px 0}
.kr-blatt-zurueck .kr-btn{min-height:var(--touch);font-size:12.5px}

.kr-schritt-balken{width:56px;height:4px;border-radius:2px;background:var(--cream-300);overflow:hidden}
.kr-schritt-balken>i{display:block;height:100%;background:var(--succ);transition:width .3s var(--ease)}


.kr-zeitstrahl{display:flex;flex-direction:column;padding:2px 0}
.kr-zeit-gr{font-size:10.5px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--navy-500);margin:8px 0 2px 64px}
.kr-zeit-gr:first-child{margin-top:4px}
.kr-zeit-el{position:relative;display:grid;grid-template-columns:44px 12px minmax(0,1fr) auto;gap:0 10px;align-items:center;min-height:var(--touch);padding:4px 8px 4px 0;border-radius:11px}
.kr-zeit-el::before{content:"";position:absolute;left:59px;top:0;bottom:0;width:2px;background:var(--cream-300)}
.kr-zeit-z{font-family:var(--serif);font-size:13px;color:var(--navy-700);text-align:right}
.kr-zeit-p{width:12px;height:12px;border-radius:50%;border:2px solid var(--navy-300);background:var(--surface);position:relative;z-index:1}
.kr-zeit-el--ok .kr-zeit-p{border-color:var(--succ);background:var(--succ)}
.kr-zeit-el--rot .kr-zeit-p{border-color:var(--ral);background:var(--ral-bg)}
.kr-zeit-el--info .kr-zeit-p{border-color:var(--info)}
.kr-zeit-el--warn .kr-zeit-p{border-color:var(--warn)}
.kr-zeit-t{min-width:0;border:0;background:transparent;text-align:left;padding:4px 0;border-radius:8px;min-height:40px;display:flex;flex-direction:column;justify-content:center}
.kr-zeit-t:hover{background:var(--cream-100)}
.kr-zeit-t>span:first-child{font-size:13px;font-weight:600;color:var(--navy-900);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.kr-zeit-t .kr-id{margin-right:7px;font-size:12.5px}
.kr-zeit-t>small{font-size:11.5px;color:var(--navy-500);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.kr-zeit-seite{display:flex;align-items:center;gap:8px}
.kr-jetzt{display:grid;grid-template-columns:44px minmax(0,1fr);gap:0 10px;align-items:center;margin:2px 0;padding-right:8px}
.kr-jetzt>span{text-align:right;font-family:var(--serif);font-size:12px;color:var(--magenta)}
.kr-jetzt>i{height:2px;background:var(--magenta);border-radius:2px;position:relative;margin-left:10px}
.kr-jetzt>i::before{content:"";position:absolute;left:-5px;top:-3px;width:8px;height:8px;border-radius:50%;background:var(--magenta)}
.kr-raster--zeit{grid-template-columns:minmax(0,1.3fr) minmax(0,1fr)}
.kr-app[data-geraet="handy"] .kr-raster--zeit{grid-template-columns:1fr}
.kr-app[data-geraet="handy"] .kr-zeit-el{grid-template-columns:40px 12px minmax(0,1fr) auto;gap:0 8px}
.kr-app[data-geraet="handy"] .kr-zeit-el::before{left:53px}
.kr-app[data-geraet="handy"] .kr-zeit-gr{margin-left:58px}
.kr-app[data-geraet="handy"] .kr-zeit-el .kr-btn{padding:0 12px}


.kr-eingang-nav{position:sticky;top:-16px;z-index:2;background:var(--surface);margin:-16px -18px 0;padding:10px 18px 8px;border-bottom:1px solid var(--line)}
.kr-eingang-nav .kr-schritt-nav button:disabled{cursor:pointer}
.kr-abschnitt{display:flex;flex-direction:column;gap:10px;scroll-margin-top:72px}
.kr-abschnitt+.kr-abschnitt{padding-top:6px}

/* ===== groessen_v8.css ===== */
.kr-app[data-groesse="v8"]{font-size:15px}
.kr-app[data-groesse="v8"] .kr-nav{font-size:16.5px;min-height:52px;font-weight:600}
.kr-app[data-groesse="v8"] .kr-nav .kr-i{font-size:20px}
.kr-app[data-groesse="v8"] .kr-suche{min-height:48px}
.kr-app[data-groesse="v8"] .kr-suche-ph{font-size:15px}
.kr-app[data-groesse="v8"] .kr-seite-titel{font-size:30px}
.kr-app[data-groesse="v8"] .kr-hb-titel{font-size:16.5px}
.kr-app[data-groesse="v8"] .kr-fokus .kr-hb-titel{font-size:18.5px}
