.kr-app[data-groesse="v8"] .kr-btn{font-size:14.5px;min-height:48px}
.kr-app[data-groesse="v8"] .kr-btn .kr-i{font-size:18px}
.kr-app[data-groesse="v8"] .kr-zeile-t{font-size:14.5px}
.kr-app[data-groesse="v8"] .kr-zeile-s{font-size:13px}
.kr-app[data-groesse="v8"] .kr-zeile{min-height:52px}
.kr-app[data-groesse="v8"] .kr-kachel-titel{font-size:13px}
.kr-app[data-groesse="v8"] .kr-chip{font-size:11.5px}
.kr-app[data-groesse="v8"] .kr-feld-label{font-size:12px}
.kr-app[data-groesse="v8"] .kr-eingabe,.kr-app[data-groesse="v8"] .kr-auswahl,.kr-app[data-groesse="v8"] .kr-textfeld{font-size:15.5px;min-height:52px}
.kr-app[data-groesse="v8"] .kr-segment button{font-size:14px;min-height:48px}
.kr-app[data-groesse="v8"] .kr-check{min-height:48px;font-size:14.5px}
.kr-app[data-groesse="v8"] .kr-qa{font-size:13px;min-height:64px}
.kr-app[data-groesse="v8"] .kr-dock-el{font-size:12px}
.kr-app[data-groesse="v8"] .kr-aktion{font-size:15px;height:60px}
.kr-app[data-groesse="v8"] .kr-treffer-t,.kr-app[data-groesse="v8"] .kr-tun,.kr-app[data-groesse="v8"] .kr-menue-el{font-size:15px}
.kr-app[data-groesse="v8"] .kr-zeit-t{min-height:48px;font-size:14.5px}
.kr-app[data-groesse="v8"] .kr-dialog-titel{font-size:23px}
.kr-app[data-groesse="v8"] .kr-karte-titel{font-size:31px}
.kr-app[data-groesse="v8"] .kr-ausgrau{font-size:14px;min-height:48px}
.kr-app[data-groesse="v8"] .kr-ausgrau-tag{font-size:10.5px}
.kr-app[data-groesse="v8"] .kr-block-label{font-size:12.5px}

.kr-app[data-groesse="v8"] .kr-suchfeld{min-height:48px}
.kr-app[data-groesse="v8"] .kr-bild{min-width:48px;min-height:48px}
.kr-app[data-groesse="v8"]:not([data-geraet="desktop"]) button.kr-pill{min-height:48px;padding-left:12px;padding-right:12px}
.kr-app[data-geraet="handy"][data-groesse="v8"] .kr-hb-titel{font-size:15px}
.kr-app[data-geraet="handy"][data-groesse="v8"] .kr-fokus .kr-hb-titel{font-size:16.5px}
.kr-app[data-geraet="handy"][data-groesse="v8"] .kr-seite-titel{font-size:24px}


.kr-ausgrau--geplant{border:1.5px dashed var(--rand);background:transparent}
.kr-ausgrau--geplant .kr-ausgrau-tag{background:var(--info-bg);color:var(--info-fg)}
.kr-ausgrau--geplant.kr-ausgrau--nav{border-color:var(--navy-600);color:var(--navy-300)}

/* ===== ui_ergaenzung.css ===== */
:root{

  --ground:#FFFFFF;--ground-rail:#F5F6F8;--surface:#FFFFFF;--flaeche:#F5F6F8;--line:#E3E6EB;--rand:#D0D5DD;
  --cream-50:#FAFBFC;--cream-100:#F5F6F8;--cream-200:#EDEFF2;--cream-300:#E3E6EB;--cream-400:#CBD0D8;--cream-500:#AEB4BF;

  --r-xs:4px;--r-s:6px;--r-m:8px;--r-btn:8px;--r-l:10px;--r-eintrag:10px;--r-kachel:12px;--r-dialog:14px;
  --ev-balken:6px;--ev-sh-karte:0 1px 2px rgba(18,22,31,.06),0 3px 10px rgba(18,22,31,.07);--ev-sh-karte-hover:0 2px 4px rgba(18,22,31,.07),0 8px 22px rgba(18,22,31,.10);
  --ev-navy-a1:rgba(38,44,60,.06);--ev-navy-a2:rgba(38,44,60,.11);--ev-navy-a3:rgba(38,44,60,.17);
}
body{background:var(--ground)}
.kr-chip,.kr-segment,.kr-pill--leise{background:var(--cream-200)}
.kr-bild{background:linear-gradient(135deg,var(--navy-400),var(--navy-600))}
.kr-toast>.kr-i{color:var(--succ-bg)}


.kr-btn--dringend1{background:var(--warn-bg);border-color:var(--warn-bd);color:var(--warn-fg)}
.kr-btn--dringend1:hover{background:var(--warn);border-color:var(--warn);color:#fff}
.kr-btn--dringend2{background:var(--ral-bg);border-color:var(--ral-bd);color:var(--ral-fg)}
.kr-btn--dringend2:hover{background:var(--ral);border-color:var(--ral);color:#fff}
.kr-btn--dringend3{background:var(--ral);border-color:var(--ral);color:#fff;box-shadow:0 2px 8px rgba(175,43,30,.28)}
.kr-btn--dringend3:hover{background:var(--ral-fg);border-color:var(--ral-fg)}


.kr-hb-eintrag{border-left-width:var(--ev-balken);grid-template-columns:minmax(0,1fr) auto}
.kr-hb-eintrag>.kr-punkt{display:none}
.kr-hb-eintrag{background:var(--surface);border-color:var(--line)}
.kr-hb-eintrag--konflikt{border-left-color:var(--ral)}
.kr-hb-eintrag--warnung{border-left-color:var(--warn)}
.kr-hb-eintrag--entscheidung{border-left-color:var(--info)}
.kr-fokus{grid-template-columns:minmax(0,1fr);grid-template-areas:"m" "a";border-left-width:8px}
.kr-fokus>.kr-hb-aktionen{padding-left:0}

.kr-app[data-geraet="desktop"] .kr-fokus{grid-template-columns:minmax(0,1fr) auto;grid-template-areas:"m a";row-gap:0;padding:14px 14px 14px 18px}
.kr-app[data-geraet="desktop"] .kr-fokus>.kr-hb-aktionen{flex-wrap:nowrap}
.kr-app[data-geraet="desktop"] .kr-fokus>.kr-hb-aktionen>.kr-btn:first-child{min-width:150px}
.kr-app[data-geraet="desktop"] .kr-spalten .kr-hb-aktionen>.kr-btn:first-child{min-width:0!important}
.kr-btn--ton-blau{background:#EAF0F8;border-color:#B7C5DC;color:#1F3A66}
.kr-btn--ton-blau:hover{background:var(--info);border-color:var(--info);color:#fff}


.ev-scan{width:var(--touch);height:var(--touch);flex:none;display:grid;place-items:center;border:1.5px solid var(--rand);border-radius:var(--r-btn);background:var(--surface);color:var(--navy-700);font-size:21px;box-shadow:var(--sh-sm);margin-left:-6px}
.ev-scan:hover{background:var(--ev-navy-a1);border-color:var(--navy-400)}
.kr-shell .kr-suche{height:var(--touch)}


.ev-sucher{position:relative;aspect-ratio:16/10;max-width:100%;border-radius:var(--r-kachel);overflow:hidden;background:var(--navy-900);display:grid;place-items:center}
.ev-sucher video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.ev-sucher-rahmen{position:absolute;inset:9% 12%;border-radius:14px;box-shadow:0 0 0 9999px rgba(18,22,31,.35);border:2px solid rgba(255,255,255,.85)}
.ev-sucher-text{position:relative;color:var(--cream-100);font-size:13.5px;padding:0 24px;text-align:center}


.ev-feld{border:2px dashed var(--navy-300);border-radius:var(--r-kachel);background:var(--surface);padding:8px;display:flex;flex-direction:column;gap:8px}
.ev-feld--fest{border-style:solid;border-color:var(--rand)}
.ev-feld-kopf{display:flex;align-items:center;gap:8px}
.ev-feld-nr{width:32px;height:32px;border-radius:50%;flex:none;display:grid;place-items:center;background:var(--navy-800);color:#fff;font-size:13px;font-weight:700}
.ev-feld-wahl{flex:1;min-width:0;font-weight:600}
.ev-feld-fest{flex:1;font-size:14px;font-weight:600;color:var(--navy-800)}
.ev-feld-werkzeug{display:flex;gap:2px;flex:none}
.ev-feld-werkzeug [data-feld-hoch] .kr-i{transform:rotate(180deg)}
.ev-feld-werkzeug [data-nach="links"] .kr-i{transform:rotate(180deg)}
.ev-feld-vorschau{max-height:200px;overflow:hidden;pointer-events:none;opacity:.55;-webkit-mask-image:linear-gradient(#000 60%,transparent);mask-image:linear-gradient(#000 60%,transparent)}
.ev-feld-neu{min-height:64px;border:2px dashed var(--rand);border-radius:var(--r-kachel);background:transparent;color:var(--navy-600);font-size:14px;font-weight:600;display:flex;align-items:center;justify-content:center;gap:8px}
.ev-feld-neu:hover:not(:disabled){border-color:var(--navy-400);background:var(--ev-navy-a1)}
.ev-feld-neu:disabled{opacity:.45;cursor:default}


.ev-wbrett{display:grid;grid-template-columns:1fr;gap:28px;align-items:start}
.ev-wbrett--eins{grid-template-columns:1fr}
.ev-wspalte{--f:var(--navy-800);--f-on:#fff;--f-bg:var(--info-bg);--f-fg:var(--navy-800);display:flex;flex-direction:column;gap:8px}
.ev-wspalte--rot{--f:var(--ral);--f-bg:var(--ral-bg);--f-fg:var(--ral-fg)}
.ev-wspalte--navy{--f:var(--navy-800);--f-bg:var(--info-bg)}
.ev-wspalte--amber{--f:var(--amber);--f-on:var(--navy-900);--f-bg:var(--warn-bg);--f-fg:var(--warn-fg)}
.ev-wspalte--gruen{--f:var(--succ);--f-bg:var(--succ-bg);--f-fg:var(--succ-fg)}
.ev-wspalte--grau{--f:var(--navy-400);--f-bg:var(--flaeche);--f-fg:var(--navy-600)}
.ev-wkopf{display:flex;align-items:center;gap:10px;min-height:48px;padding:0 14px;border:0;border-radius:var(--r-m);background:var(--f);color:var(--f-on);font-size:14px;font-weight:650;letter-spacing:.01em;text-align:left;width:100%;box-shadow:none}
.ev-wkopf .kr-i{font-size:18px;color:inherit}
.ev-wkopf span{flex:1}
.ev-wkopf b{font-size:13px;font-weight:700;line-height:1;padding:5px 10px;border-radius:var(--r-xs);background:rgba(255,255,255,.18);color:inherit;font-variant-numeric:tabular-nums}
button.ev-wkopf{cursor:pointer}
button.ev-wkopf:hover{filter:brightness(1.07)}
.ev-wkopf[aria-pressed="true"]{box-shadow:0 0 0 2px var(--surface),0 0 0 4px var(--f)}
.ev-wliste{display:flex;flex-direction:column;gap:8px}
.ev-wliste--breit{width:100%}
.ev-wkarte{display:grid;grid-template-columns:56px minmax(0,1fr);gap:14px;align-items:center;padding:10px 14px 10px 12px;background:var(--surface);border:1px solid var(--line);border-left:var(--ev-balken) solid var(--f);border-radius:var(--r-l);box-shadow:var(--ev-sh-karte);cursor:pointer;transition:box-shadow .15s,border-color .15s}
.ev-wkarte:hover{box-shadow:var(--ev-sh-karte-hover)}
.ev-wbild{width:56px;height:56px;border-radius:6px;display:grid;place-items:center;font-size:20px;color:var(--navy-300);background:var(--flaeche);border:1px solid var(--line)}
.ev-wkarte-inhalt{min-width:0;display:flex;flex-direction:column;gap:3px}
.ev-wkarte-t{font-size:15px;font-weight:600;color:var(--navy-900);line-height:1.3;display:flex;align-items:baseline;gap:8px;flex-wrap:wrap}
.ev-wkarte-t .kr-id{font-size:12px;color:var(--navy-400);font-weight:400}
.ev-wkarte-m{font-size:13px;color:var(--navy-600)}
.ev-wkarte-m b{font-weight:600;color:var(--navy-800)}
.ev-wkarte-f{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:4px}
.ev-wkarte-f .kr-chip{font-size:12px;padding:4px 9px}
.ev-wliste--breit .ev-wkarte{grid-template-columns:56px minmax(0,1fr)}
.ev-wleer{padding:12px;border:1px dashed var(--rand);border-radius:var(--r-s);color:var(--navy-400);font-size:13px;text-align:center}
.kr-buendel{background:var(--surface);border:1px solid var(--line);border-left:4px solid var(--warn);border-radius:var(--r-s);box-shadow:none}
.kr-buendel>.kr-i{color:var(--warn);align-self:center;margin:0}


.ev-login{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;overflow:auto;
  background:var(--surface)}
.ev-login>.kr-streifen{position:absolute;top:0;left:0;right:0}
.ev-login-spalte{width:min(380px,100%);display:flex;flex-direction:column;align-items:center;gap:30px;padding:28px 20px}

.ev-login-marke{display:flex;align-items:center;gap:11px}
.ev-login-logo{width:40px;height:40px;border-radius:12px;background:var(--navy-800);color:var(--cream-50);font-family:var(--serif);font-size:15px;letter-spacing:.5px;display:grid;place-items:center}
.ev-login-wort{font-family:var(--serif);font-size:17px;letter-spacing:.16em;text-transform:uppercase;color:var(--navy-800)}

.ev-login-gruss{margin:0;font-family:var(--serif);font-weight:400;font-size:36px;line-height:1.1;letter-spacing:-.5px;color:var(--navy-900);text-align:center;text-wrap:balance}

.ev-login-personen{display:flex;gap:18px;justify-content:center;flex-wrap:wrap}
.ev-person{display:flex;flex-direction:column;align-items:center;gap:10px;min-width:96px;min-height:var(--touch);padding:4px;border:0;border-radius:16px;background:none;color:var(--navy-500);transition:transform .15s var(--ease)}
.ev-person-kreis{width:84px;height:84px;border-radius:50%;display:grid;place-items:center;font-size:21px;font-weight:600;letter-spacing:.02em;
  background:var(--surface);color:var(--navy-700);box-shadow:var(--sh-sm),inset 0 0 0 1px var(--line);transition:background .18s,color .18s,box-shadow .18s}
.ev-person:hover .ev-person-kreis{box-shadow:var(--sh-md),inset 0 0 0 1px var(--rand)}
.ev-person--an .ev-person-kreis{background:var(--navy-800);color:#fff;box-shadow:0 0 0 3px var(--ground),0 0 0 5px var(--amber),var(--sh-md)}
.ev-person-name{font-size:14.5px;font-weight:500}
.ev-person--an .ev-person-name{color:var(--navy-900);font-weight:600}

.ev-login-code{display:flex;flex-direction:column;align-items:center;gap:13px}

.ev-pin{display:flex;align-items:center;gap:18px;height:18px}
.ev-pin-p{width:13px;height:13px;border-radius:50%;box-shadow:inset 0 0 0 1.5px var(--navy-300);transition:background .15s,box-shadow .15s,transform .15s var(--ease)}
.ev-pin-p--an{background:var(--navy-800);box-shadow:none;transform:scale(1.08)}
.ev-pin--fehler{animation:ev-schuetteln .42s var(--ease)}
.ev-pin--fehler .ev-pin-p{box-shadow:inset 0 0 0 1.5px var(--ral)}
@keyframes ev-schuetteln{20%{transform:translateX(-7px)}40%{transform:translateX(6px)}60%{transform:translateX(-4px)}80%{transform:translateX(2px)}}
.ev-login-meldung{min-height:18px;font-size:12.5px;font-weight:600;color:var(--ral-fg);text-align:center}

.ev-tasten{display:grid;grid-template-columns:repeat(3,74px);gap:14px 28px;justify-content:center}
.ev-taste{width:74px;height:74px;border-radius:50%;border:0;display:grid;place-items:center;background:var(--ev-navy-a1);color:var(--navy-800);
  font-size:25px;font-weight:400;font-variant-numeric:tabular-nums;transition:transform .12s var(--ease),background-color .15s}
.ev-taste:hover{background:var(--ev-navy-a2)}
.ev-taste:active{transform:scale(.94);background:var(--ev-navy-a3)}
.ev-taste--leise{background:transparent;box-shadow:none;color:var(--navy-500);font-size:22px}
.ev-taste--leise:hover{background:var(--ev-navy-a1)}
.ev-taste-leer{width:74px;height:74px}

.ev-login-link{min-height:var(--touch);padding:0 14px;border:0;border-radius:var(--r-btn);background:none;font-size:13.5px;font-weight:500;color:var(--navy-500);
  text-decoration:underline;text-underline-offset:4px;text-decoration-color:var(--rand)}
.ev-login-link:hover{color:var(--navy-800);text-decoration-color:var(--navy-400)}
.ev-login-form{width:100%;display:flex;flex-direction:column;gap:12px}
.ev-login-form .kr-btn{margin-top:6px}

.kr-app[data-geraet="handy"] .ev-login-spalte{gap:22px;padding:20px 16px}
