.ev-ma-range{-webkit-appearance:none;appearance:none;width:100%;height:16px;border-radius:8px;background:linear-gradient(to right,var(--succ-bg) 0 var(--kv8),var(--warn-bg) var(--kv8) var(--kv),var(--ral-bg) var(--kv) 100%);outline:none;margin:8px 0}
