@media (max-width:900px){.f2-mail-inhalt{grid-template-columns:1fr}.f2-mail-rail{position:static}.f2-stand{grid-template-columns:1fr;margin:0 14px 10px}.f2-stand-r{align-items:stretch}.f2-stand-k{justify-content:flex-start}.f2-cd{align-items:flex-start}.f2-wz-zeile{grid-template-columns:56px minmax(0,1fr) 18px}.f2-wbild{width:56px;height:56px}.f2-wz-r{grid-column:1/3;flex-direction:row;justify-content:space-between;align-items:center}.f2-kurz{padding-left:12px}.f2-teil{grid-template-columns:48px minmax(0,1fr)}.f2-teil-k{grid-column:1/3;justify-content:flex-start}}
