.ev-neu-sub{font-size:12.5px;color:var(--navy-500)}
.ev-neu-zu{flex:none;width:36px;height:36px;border-radius:999px;border:1px solid var(--line);background:var(--surface);color:var(--navy-600);display:grid;place-items:center;cursor:pointer}
.ev-neu-zu:hover{background:#EAF0F8}
.ev-neu-zu svg{width:16px;height:16px}
.ev-neu-liste{list-style:none;margin:0;padding:0 8px 8px;display:flex;flex-direction:column}
.ev-neu-p{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:12px;padding:10px 8px;border-top:1px solid var(--line)}
.ev-neu-nr{min-width:44px;padding:3px 8px;border-radius:999px;background:#1F3A66;color:#fff;font-size:12px;font-weight:700;text-align:center;font-variant-numeric:tabular-nums}
.ev-neu-tx{display:flex;flex-direction:column;gap:2px;min-width:0}
.ev-neu-tx b{font-size:14px;color:var(--navy-900);font-weight:600}
.ev-neu-tx span{font-size:12.5px;line-height:1.4;color:var(--navy-500)}
.ev-neu-wege{display:flex;flex-wrap:wrap;gap:6px;justify-content:flex-end}
.ev-neu-geh{display:inline-flex;align-items:center;gap:4px;min-height:34px;padding:0 12px;border-radius:999px;border:1px solid #8FA8CE;background:#EAF0F8;color:#1F3A66;font:inherit;font-size:12.5px;font-weight:600;cursor:pointer;white-space:nowrap}
