.ev-neu-geh svg{width:14px;height:14px}
.ev-neu-hier{font-size:12px;color:var(--navy-400);font-style:italic}
.ev-neu-frueher{border-top:1px solid var(--line);padding:0 8px 8px}
.ev-neu-frueher>summary{cursor:pointer;list-style:none;padding:12px 8px;font-size:12.5px;font-weight:600;color:#3A5C8C}
.ev-neu-frueher>summary::-webkit-details-marker{display:none}
.ev-neu-frueher>summary::before{content:"▸ ";color:#8FA8CE}
.ev-neu-frueher[open]>summary::before{content:"▾ "}
.ev-neu-runde h4{margin:6px 8px 2px;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--navy-600)}
.ev-neu-runde h4 small{font-weight:500;letter-spacing:0;text-transform:none;color:var(--navy-400)}
.ev-neu-runde .ev-neu-liste{padding:0}
.ev-neu-puls{outline:3px solid #3A5C8C!important;outline-offset:3px;border-radius:8px;animation:evNeuPuls 1.2s ease-in-out 3}
@keyframes evNeuPuls{0%,100%{box-shadow:0 0 0 0 rgba(58,92,140,.0)}50%{box-shadow:0 0 0 8px rgba(58,92,140,.28)}}
.ev-neu-geh svg{transform:rotate(-90deg)}

.ev-neu-kn{flex:none;display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end}
.ev-neu-weiter{display:inline-flex;align-items:center;gap:6px;min-height:36px;padding:0 14px;border-radius:999px;border:0;background:#1F3A66;color:#fff;font:inherit;font-size:13px;font-weight:600;cursor:pointer;box-shadow:var(--sh-sm)}
