.ev-neu-leer{display:flex;align-items:center;gap:10px;margin:0 16px 14px;padding:12px 14px;border-radius:12px;background:var(--succ-bg);color:var(--succ-fg);font-size:13.5px;font-weight:500}
.ev-neu-leer svg{width:20px;height:20px;flex:none}
.ev-neu--ruhig .ev-neu-kopf{padding-bottom:12px}
.ev-neu-leiste{display:inline-flex;gap:6px;margin-right:6px}
