.ev-neu-zeile{display:flex;align-items:center;gap:10px;width:100%;min-height:48px;padding:10px 14px;margin-bottom:12px;border-radius:12px;border:1px solid #8FA8CE;background:#EAF0F8;color:#1F3A66;font:inherit;font-size:14px;cursor:pointer;text-align:left}
