.ev-neu-t{display:inline-flex;align-items:center;gap:4px;min-height:36px;padding:4px 10px;border-radius:8px;border:1px solid var(--line);background:var(--surface);font:inherit;font-size:12.5px;color:var(--navy-700);cursor:pointer}
