.ev-neu-t--ok{background:var(--succ);border-color:var(--succ-d);color:#fff}
.ev-neu-t--pr{background:#F6DCE7;border-color:#C2185B;color:#8E1449}
.ev-neu-navb{margin-left:auto;min-width:20px;height:20px;padding:0 6px;border-radius:999px;background:#C2185B;color:#fff;font-size:11px;display:inline-flex;align-items:center;justify-content:center}


.ev-neu-navb--ruhig{background:#EAF0F8;color:#1F3A66}
